#[test]
fn sqlite_snapshot_collection_original_receiving_cumulative(){
 let c=contract();let input=source(&c["cases"][0]);let database=database(&c["cases"][0]);let coordinate=dialect();macro_rules! prior{($native:ident,$owner:ident,$recipient:path,$method:ident)=>{{let mut callback=|_|true;let mut native=semio_framework_value::$native::new(c["nativeMaximumBytes"].as_u64().unwrap()as usize,&mut callback);let mut recipient=<$recipient>::new();native.install_retirement_recipient(&mut recipient).unwrap();let mut callback=|_|true;let mut sql=SqliteSnapshotControl::new(&mut callback,SqliteDatabaseLimits{max_allocation_bytes:c["sqlMaximumBytes"].as_u64().unwrap()as usize,..Default::default()});let(seed,seed_heap)=observe(||native.allocate_vec::<u8>(c["priorBaseline"]["nativeBytes"].as_u64().unwrap()as usize).unwrap());assert_eq!((seed_heap.requested_bytes,seed_heap.released_bytes),(32,0));let seed_pointer=seed.as_ptr();sql.admit_native_allocation_bytes(c["priorBaseline"]["sqlBytes"].as_u64().unwrap()as usize).unwrap();let native_before=native.owned_bytes();let remaining=sql.allocation_remaining_bytes();let mut owner=$owner::new(&mut native,grant());let(result,heap)=observe(||input.$method(&coordinate,&database,&mut sql,&mut owner));result.unwrap();let first=owner.progress();assert!(first.retained_capacity_bytes>0&&first.released_bytes>0);assert_eq!((heap.requested_bytes,heap.released_bytes),(first.retained_capacity_bytes,first.released_bytes));let(result,heap)=observe(||input.$method(&coordinate,&database,&mut sql,&mut owner));result.unwrap();let total=owner.progress();assert_eq!((heap.requested_bytes,heap.released_bytes),(total.retained_capacity_bytes-first.retained_capacity_bytes,total.released_bytes-first.released_bytes));
 for axis in 0..3{let mut wrong=dialect();match axis{0=>wrong.artifact_kind="wrong".into(),1=>wrong.standard="wrong".into(),_=>wrong.subset="wrong".into()}let(result,heap)=observe(||input.$method(&wrong,&database,&mut sql,&mut owner));let error=result.unwrap_err();assert_eq!(error.cause.kind,ValueRefusalKind::InvalidValue);assert_eq!(error.cause.message,"Collection owned SQLite dialect differs");assert_eq!(error.cause.retained_progress(),owner.progress());assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));}drop(owner);assert!(!native.has_retirement_owner());assert_eq!(remaining-sql.allocation_remaining_bytes(),native.owned_bytes()-native_before);assert_eq!(seed.as_ptr(),seed_pointer);let(born,released)=close(seed);assert_eq!(native_before+born,released);}};}
 prior!(NativeDecodeControl,NativeSnapshotDecodeOwner,semio_framework_value::native_decoding::NativeDecodeRetirementRecipient,validate_sqlite_snapshot_subset_decoding);prior!(NativeEncodeControl,NativeSnapshotEncodeOwner,semio_framework_value::native_encoding::NativeEncodeRetirementRecipient,validate_sqlite_snapshot_subset_encoding);
 eprintln!("[DEBUG] Collection physical32byte prior baseline/two cumulative validates/three wrong dialects preserve original callback, wallet, SQL/native deltas and zero wrong-dialect heap");
}
#[test]
fn sqlite_snapshot_collection_original_receiving_boxed_custody(){
 use semio_framework_os_kernel::io::control::NativeSnapshotBodyWallet;
 use semio_framework_os_kernel::sqlite_snapshot::artifact::receiving::{Direction,Port};
 use std::{cell::Cell,mem::size_of};
 macro_rules! cases{($native:ident,$direction:ident)=>{for frontier in contract()["boxedBody"]["frontiers"].as_array().unwrap(){let mode=frontier["mode"].as_u64().unwrap();let constructed=Cell::new(0);let mut policy=grant();let size=size_of::<super::ArtifactBody>();match mode{1=>policy.maximum_items=0,2=>policy.maximum_copy_bytes=size+size_of::<Box<super::ArtifactBody>>()-1,3=>policy.maximum_capacity_bytes=size-1,4=>policy.maximum_depth=0,_=>{}}let mut callback=|_|mode!=7;let mut sql=SqliteSnapshotControl::new(&mut callback,SqliteDatabaseLimits{max_allocation_bytes:if mode==5{0}else{65536},..Default::default()});let sql_before=sql.allocation_remaining_bytes();let mut callback=|_|mode!=8;let mut native=semio_framework_value::$native::new(if mode==6{0}else{65536},&mut callback);let mut body=NativeSnapshotBodyWallet::new(policy);let mut output=None;let mut port=Port{control:&mut sql,native:Direction::$direction(&mut native),body:&mut body};let(result,heap)=observe(||port.boxed(&mut output,||{constructed.set(constructed.get()+1);super::ArtifactBody::Document{schema:String::new(),document_id:String::new()}},3));drop(port);if mode==0{result.unwrap();assert_eq!(constructed.get(),1);assert!(output.is_some());assert_eq!((heap.requested_bytes,heap.released_bytes),(size,0));assert_eq!(body.progress().retained_capacity_bytes,size);assert_eq!(body.progress().copied_items,1);assert_eq!(native.owned_bytes(),size);assert_eq!(sql_before-sql.allocation_remaining_bytes(),size);let(born,released)=close(output);assert_eq!(size+born,released)}else{let error=result.unwrap_err();assert!(matches!(error.kind,ValueRefusalKind::Canceled|ValueRefusalKind::OwnershipLimit|ValueRefusalKind::WorkLimit|ValueRefusalKind::DepthLimit));assert!(matches!(error.message,std::borrow::Cow::Borrowed(_)));assert_eq!(constructed.get(),0);assert!(output.is_none());assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));assert_eq!(body.progress(),Default::default());assert_eq!(native.owned_bytes(),0);assert_eq!(sql.allocation_remaining_bytes(),sql_before)}}};}
 cases!(NativeDecodeControl,Decode);cases!(NativeEncodeControl,Encode);
 let literal="Collection boxed 世界\0🌠".repeat(257);for mode in[1,2]{let copied=std::cell::Cell::new(0);let capacity=std::cell::Cell::new(0);let pointer=std::cell::Cell::new(0);let(result,born,released)=encode(grant(),literal.len(),mode,|sql,owner,_|owner.receive_sqlite_snapshot(sql,super::Frame::new,|frame,port|{
  port.boxed(&mut frame.pending_body,||super::ArtifactBody::Document{schema:String::new(),document_id:String::new()},3)?;let super::ArtifactBody::Document{schema,document_id}=frame.pending_body.as_mut().unwrap().as_mut()else{unreachable!()};let result=port.text(&literal,schema,4);copied.set(schema.len());capacity.set(schema.capacity());pointer.set(schema.as_ptr()as usize);assert!(document_id.is_empty());if mode==1{assert!(result.is_err())}result
 },|_|->Result<(),ValueError>{panic!("canceled boxed body cannot publish")}));assert_eq!(result.unwrap_err().kind,ValueRefusalKind::Canceled);assert!(copied.get()>0&&capacity.get()>=copied.get()&&pointer.get()!=0);assert_eq!(born,released);}
 let c=contract();let input=source(&c["cases"][0]);let database=database(&c["cases"][0]);for mode in[3,4,5,6]{for operation in 0..4{let published=AtomicBool::new(false);let(result,born,released)=match operation{
 0=>decode(grant(),0,mode,|sql,owner,body_completed|owner.receive_sqlite_snapshot(sql,super::Frame::new,|frame,port|{super::project(&input,frame,port)?;body_completed.store(true,Ordering::Relaxed);if mode>=5{Err(ValueError::literal(ValueRefusalKind::InvalidValue,FAILED_BODY))}else{Ok(())}},|_|{published.store(true,Ordering::Relaxed);Ok(())})),
 1=>encode(grant(),0,mode,|sql,owner,body_completed|owner.receive_sqlite_snapshot(sql,super::Frame::new,|frame,port|{super::read(&database,frame,None,port)?;body_completed.store(true,Ordering::Relaxed);if mode>=5{Err(ValueError::literal(ValueRefusalKind::InvalidValue,FAILED_BODY))}else{Ok(())}},|_|{published.store(true,Ordering::Relaxed);Ok(())})),
 2=>decode(grant(),0,mode,|sql,owner,body_completed|owner.receive_sqlite_snapshot(sql,super::Frame::new,|frame,port|{super::read(&database,frame,Some(&input),port)?;body_completed.store(true,Ordering::Relaxed);if mode>=5{Err(ValueError::literal(ValueRefusalKind::InvalidValue,FAILED_BODY))}else{Ok(())}},|_|{published.store(true,Ordering::Relaxed);Ok(())})),
 _=>encode(grant(),0,mode,|sql,owner,body_completed|owner.receive_sqlite_snapshot(sql,super::Frame::new,|frame,port|{super::read(&database,frame,Some(&input),port)?;body_completed.store(true,Ordering::Relaxed);if mode>=5{Err(ValueError::literal(ValueRefusalKind::InvalidValue,FAILED_BODY))}else{Ok(())}},|_|{published.store(true,Ordering::Relaxed);Ok(())}))
 };assert!(!published.load(Ordering::Relaxed));assert_eq!(result.unwrap_err().kind,if mode<5{ValueRefusalKind::Canceled}else{ValueRefusalKind::InvalidValue});assert_eq!(born,released);}}
 eprintln!("[DEBUG] Collection both original directions deny box construction on8 independent frontiers with System0; accepted boxed backing retains exact physical receipts; all4 complete/failed body statuses precede publication and same-recipient finite close");
}
